package com.vibeguard.samples.sessions; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.time.*; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Creates expiring login sessions for a trusted upstream authentication service. */ @RestController @RequestMapping("/internal/sessions") public class SessionController { private final Map<String,Session> sessions=new ConcurrentHashMap<>(); @Value("${LOGIN_EVENTS_KEY:}") private String eventsKey; @PostMapping public ResponseEntity<Session> start(@RequestHeader("X-Login-Events-Key") String key,@Valid @RequestBody Request request){if(!allowed(key))return ResponseEntity.status(401).build();Session session=new Session(UUID.randomUUID().toString(),request.userId(),Instant.now().plus(Duration.ofHours(8)));sessions.put(session.id(),session);return ResponseEntity.status(201).body(session);}@GetMapping("/{id}") public ResponseEntity<Session> valid(@RequestHeader("X-Login-Events-Key") String key,@PathVariable String id){if(!allowed(key))return ResponseEntity.status(401).build();Session session=sessions.get(id);return session==null||Instant.now().isAfter(session.expiresAt())?ResponseEntity.notFound().build():ResponseEntity.ok(session);}@DeleteMapping("/{id}") public ResponseEntity<Void> end(@RequestHeader("X-Login-Events-Key") String key,@PathVariable String id){if(!allowed(key))return ResponseEntity.status(401).build();sessions.remove(id);return ResponseEntity.noContent().build();}private boolean allowed(String key){return !eventsKey.isBlank()&&eventsKey.equals(key);}record Request(@NotBlank String userId){}record Session(String id,String userId,Instant expiresAt){} }
